def _call_legacy(name, *args, **kwargs):

    db = _db()

    legacy_name = f"_legacy_equipment_ro_v1_{name}"

    legacy = getattr(db, legacy_name, None)



    if legacy is None:

        raise AttributeError(f"Legacy equipment read-only function not found: {legacy_name}")



    return legacy(*args, **kwargs)

def is_armor_slot(slot_key):

    """Return True only for the six physical armor slots."""

    return str(slot_key or "") in _ARMOR_SLOT_KEYS

def can_equip_item_by_class(user_id, item_info):

    db = _db()



    if not item_info:

        return {

            "success": False,

            "message": "❌ Предмет не знайдено."

        }



    if item_info.get("category") != "equipment":

        return {

            "success": True,

            "message": ""

        }



    class_key = db.get_character_class(user_id)

    if not class_key:

        return {

            "success": False,

            "message": "❌ Спочатку обери клас персонажа."

        }



    checks = (

        db.check_armor_compatibility_for_class,

        db.check_main_hand_compatibility_for_class,

        db.check_off_hand_compatibility_for_class,

    )

    for check in checks:

        result = check(class_key, item_info)

        if not result["success"]:

            return result



    result = db.check_two_handed_conflict_for_equip(user_id, item_info)

    if not result["success"]:

        return result



    return {

        "success": True,

        "message": ""

    }

