            result = None


            for _ in range(safe_amount):


                result = legacy(user_id)


            return result





    try:


        safe_amount = max(1, int(amount or 1))


        _execute_commit(


            "UPDATE users SET kills=COALESCE(kills, 0)+? WHERE user_id=?",


            (safe_amount, user_id),


